return { json: {
  monitorVersion: 'local-ai-operations-monitor-v1',
  thresholds: {
    workerStaleSeconds: 120,
    ramPercent: 85,
    diskPercent: 85,
    queueOldestSeconds: 300,
    jobDurationSeconds: 180,
    failureRatePercent: 20,
    failureRateMinimumJobs: 5,
  },
} };

const request = $('Prepare Monitor Cycle').item.json;
const response = $json;
const statusCode = Number(response.statusCode ?? 0);
const unauthorized = statusCode === 401 || statusCode === 403;
const body = response.body ?? {};
const health = body.health ?? {};
const retryAfterSeconds = Number(response.headers?.['retry-after'] ?? 0) || null;
const incidentCategories = [];
if (unauthorized) incidentCategories.push('upstream-unauthorized');
if (statusCode !== 200 || body.status !== 'ready') incidentCategories.push('health-unavailable');
if (statusCode === 200 && health.workerFresh !== true) incidentCategories.push('worker-stale');
if (statusCode === 200 && health.ollamaReady !== true) incidentCategories.push('ollama-not-ready');
if (statusCode === 200 && health.acceptingPrivateJobs !== false) incidentCategories.push('private-jobs-gate-invalid');
if (statusCode === 200 && Number(health.oldestQueueSeconds ?? 0) > request.thresholds.queueOldestSeconds) incidentCategories.push('queue-oldest-high');
if (statusCode === 200 && Number(health.durationP95Ms ?? 0) > request.thresholds.jobDurationSeconds * 1000) incidentCategories.push('job-duration-high');
if (statusCode === 200 && Number(health.failed24h ?? 0) > 0) incidentCategories.push('failed-jobs-present');
if (statusCode === 200 && Number(health.queued ?? 0) + Number(health.leased ?? 0) >= 25) incidentCategories.push('active-queue-cap-reached');
return { json: {
  outcome: unauthorized ? 'failed' : incidentCategories.length ? 'attention-required' : 'healthy',
  monitorVersion: request.monitorVersion,
  incidentNeeded: incidentCategories.length > 0,
  incidentCategories,
  retryAfterSeconds,
  health: statusCode === 200 ? {
    queued: Number(health.queued ?? 0),
    leased: Number(health.leased ?? 0),
    pendingReview: Number(health.pendingReview ?? 0),
    succeeded24h: Number(health.succeeded24h ?? 0),
    failed24h: Number(health.failed24h ?? 0),
    oldestQueueSeconds: Number(health.oldestQueueSeconds ?? 0),
    durationP50Ms: Number(health.durationP50Ms ?? 0),
    durationP95Ms: Number(health.durationP95Ms ?? 0),
    workerFresh: health.workerFresh === true,
    ollamaReady: health.ollamaReady === true,
    acceptingPrivateJobs: health.acceptingPrivateJobs === true,
  } : null,
  errorCategory: statusCode === 200 ? null : (body.error ?? 'local-ai-unavailable'),
} };

const assessment = $('Assess Operations Health').item.json;
const response = $json;
const body = response.body ?? {};
const incidents = Array.isArray(body.incidents) ? body.incidents.map((item) => ({
  jobId: item.jobId,
  taskType: item.taskType,
  status: item.status,
  queueClass: item.queueClass,
  attempts: item.attempts,
  errorCategory: item.errorCategory ?? null,
  updatedAt: item.updatedAt,
})) : [];
return { json: {
  ...assessment,
  incidents,
  incidentReadError: response.statusCode !== undefined && Number(response.statusCode) !== 200
    ? (body.error ?? 'incident-read-unavailable')
    : null,
} };
